<script setup lang="ts">
import{computed,ref}from"vue";import CrudTable from"../../components/CrudTable.vue";import{bzaApi,hasBzaPermission}from"../auth/session";
const columns=["permissionId","roleCode","menuCode","buttonCode","permissionType","httpMethod","apiPattern","dataScope","allowYn","useYn"];
const fields=[{name:"permissionId",label:"Permission ID",type:"number"},{name:"roleCode",label:"Role 코드",required:true},{name:"menuCode",label:"메뉴 코드",required:true},{name:"buttonCode",label:"행위 코드",required:true},{name:"permissionType",label:"권한 유형",required:true},{name:"httpMethod",label:"HTTP Method"},{name:"apiPattern",label:"API Pattern"},{name:"domainCode",label:"Domain 코드"},{name:"environmentCode",label:"환경 코드"},{name:"dataScope",label:"Data Scope"},{name:"allowYn",label:"허용",type:"yn"},{name:"useYn",label:"사용",type:"yn"}];
const loginId=ref(""),effective=ref<Record<string,any>[]>([]),error=ref("");const grouped=computed(()=>Object.entries(effective.value.reduce((a:Record<string,any[]>,r)=>{const k=String(r.menuCode||r.resourceCode||'UNKNOWN');(a[k]??=[]).push(r);return a},{})));
async function simulate(){if(!loginId.value.trim()){error.value='Login ID를 입력하세요.';return}try{effective.value=await bzaApi(`/api/bza/backoffice/permissions/effective?loginId=${encodeURIComponent(loginId.value.trim())}`);error.value=''}catch(e){error.value=e instanceof Error?e.message:String(e)}}
</script>
<template><div class="page-stack"><div class="cpf-page-heading"><div><p class="eyebrow">EFFECTIVE AUTHORIZATION</p><h2>권한</h2><p>Role·Menu·Button·API·Data Scope 정본과 사용자 실효 권한을 함께 검증합니다.</p></div></div><section class="cpf-card"><div class="cpf-card-head"><h2>실효 권한 시뮬레이션</h2><span class="cpf-status info">fail-closed</span></div><div class="cpf-card-body"><div class="cpf-toolbar"><input v-model="loginId" placeholder="Login ID"><button v-if="hasBzaPermission('AUTHORIZATION','SIMULATE')" class="primary" @click="simulate">검사</button></div><p v-if="error" class="error-banner">{{error}}</p><div v-if="grouped.length" class="permission-groups"><article v-for="[menu,items] in grouped" :key="menu" class="cpf-card"><div class="cpf-card-head"><h3>{{menu}}</h3><span class="count-pill">{{items.length}}</span></div><div class="cpf-card-body"><div v-for="item in items" :key="String(item.permissionId||item.buttonCode||item.apiPattern)" class="permission-result"><strong>{{item.buttonCode||item.actionCode||item.permissionType}}</strong><span class="cpf-status" :class="item.allowYn==='N'?'danger':'success'">{{item.allowYn==='N'?'DENY':'ALLOW'}}</span><small>{{item.httpMethod||''}} {{item.apiPattern||''}} · {{item.dataScope||'DEFAULT'}}</small><p>{{item.reason||item.source||'Role/Menu/Button/API 정본 판정'}}</p></div></div></article></div><div v-else class="cpf-empty">사용자를 조회하면 허용·거부 근거를 그룹별로 표시합니다.</div></div></section><CrudTable title="권한 Assignment" endpoint="/api/bza/permissions" menu-code="AUTHORIZATION" :columns="columns" :fields="fields" create-action="WRITE" update-action="WRITE" /></div></template>
